// Crops the P7 /types-of-personal-goals photos (Gemini P7-1 to P7-7, generated by Grant 2026-11-05) to their slots (2x) and writes one
// combined script that places them in Figma frame 116:4994 (v2.3.3, desktop) and its mobile frames. Reuses the place()/tag() helpers
// from place-p4-photos.js. The media placeholders are hidden, not deleted.
// Usage: node docs/brand/assets/site-imagery/place-p7-photos.js  →  out/p7-<slot>-{desktop,mobile}.jpg, out/p7-crops-sheet.jpg,
// and place-p7.js in the OS temp folder (run it in Figma: Chrome javascript_tool paste route, see notes/figma-pillar-v2/README.md).
// Face checks are in the crops: hero starts below the beard line; 4.3 cuts the cheek at the left; 4.5 starts below the writer's
// cheek and ends above the book spines (real titles); card 3 starts below the in-focus faces at the table.
const fs = require('fs');
const os = require('os');
const path = require('path');
const { createCanvas, loadImage } = require('../facebook/node_modules/@napi-rs/canvas');
const dir = __dirname;
const p4 = fs.readFileSync(path.join(dir, 'place-p4-photos.js'), 'utf8');
const header = p4.slice(p4.indexOf('const header = `') + 16, p4.indexOf('\n`;\n(async'));
const G = id => `Gemini_Generated_Image_${id}.jpg`;
const SLOTS = [
  { key: 'hero', src: G('vwuqhgvwuqhgvwuq'), d: { node: '116:5015', w: 460, h: 400, crop: [300, 360, 1647, 1432] }, m: { node: '116:5602', w: 335, h: 230, crop: [300, 600, 1736, 1192] },
    tag: ['Lead area · Money', 'Move $100 to savings every Friday.'], corner: 'tr' },
  { key: 'p41', src: G('405h5r405h5r405h'), d: { node: '116:5241', w: 360, h: 320, crop: [192, 0, 2016, 1792] }, m: { node: '116:5791', w: 335, h: 210, crop: [0, 288, 2400, 1504] } },
  { key: 'p43', src: G('cxr6zncxr6zncxr6'), d: { node: '116:5279', w: 360, h: 300, crop: [400, 125, 2000, 1667] }, m: { node: '116:5846', w: 335, h: 210, crop: [400, 400, 2000, 1254] } },
  { key: 'p45', src: G('wnil12wnil12wnil'), d: { node: '116:5377', w: 360, h: 320, crop: [800, 350, 990, 880] }, m: { node: '116:5903', w: 335, h: 210, crop: [720, 500, 1117, 700] } },
  { key: 'p410a', src: G('y7vk3oy7vk3oy7vk'), d: { node: '116:5502', w: 286, h: 180, crop: [150, 0, 2441, 1536] }, m: { node: '116:6045', w: 260, h: 150, crop: [45, 0, 2662, 1536] } },
  { key: 'p410b', src: G('s8iunes8iunes8iu'), d: { node: '116:5509', w: 286, h: 180, crop: [155, 0, 2441, 1536] }, m: { node: '116:6052', w: 260, h: 150, crop: [45, 0, 2662, 1536] } },
  { key: 'p410c', src: G('fzdo2nfzdo2nfzdo'), d: { node: '116:5516', w: 286, h: 180, crop: [840, 830, 1122, 706] }, m: { node: '116:6059', w: 260, h: 150, crop: [790, 830, 1224, 706] } },
];
async function crop(file, [x, y, w, h], ow, oh, out) {
  const img = await loadImage(path.join(dir, 'source', file));
  const c = createCanvas(ow * 2, oh * 2); c.getContext('2d').drawImage(img, x, y, w, h, 0, 0, ow * 2, oh * 2);
  const buf = c.toBuffer('image/jpeg', 84); fs.writeFileSync(out, buf); return buf.toString('base64');
}
// Batch 2 (2026-11-05, Grant): recrop 4.5 to show the books (swaps the image fill in the placed photo frames 117:6226/6227),
// and place the 4.7 product UI (week-board, one goal per tracking mode; specs product-views/examples/pillar-types-of-goals-shapes*.json).
// The product slots are resized to the render's aspect ratio. Usage: node place-p7-photos.js 2 → place-p7-batch2.js in the OS temp folder.
const B2 = {
  p45: { src: G('wnil12wnil12wnil'), d: { node: '117:6226', w: 360, h: 320, crop: [340, 560, 1170, 1040] }, m: { node: '117:6227', w: 335, h: 210, crop: [300, 700, 1404, 880] } },
  ui: { d: { node: '116:5465', file: '../product-views/out/pillar-types-of-goals-shapes-2000x1200-bare.png', w: 900, crop: [0, 0, 1960, 1018] },
        m: { node: '116:5963', file: '../product-views/out/pillar-types-of-goals-shapes-mobile-mobile-bare.png', w: 335, crop: [0, 30, 1170, 1200] } },
};
async function cropFile(file, [x, y, w, h], ow, oh, out, png) {
  const img = await loadImage(path.join(dir, file));
  const c = createCanvas(ow * 2, oh * 2); c.getContext('2d').drawImage(img, x, y, w, h, 0, 0, ow * 2, oh * 2);
  const buf = png ? c.toBuffer('image/png') : c.toBuffer('image/jpeg', 84); fs.writeFileSync(out, buf); return buf.toString('base64');
}
// Batch 3 (2026-11-05): swap the image in already-placed photo frames. 4.10 card 1 "On your own" is now gktj (kitchen counter,
// pencil ticking a weekly grid), replacing y7vk (closed notebook and a whisky glass).
const SWAP = [{ key: 'p410a', src: G('gktj7xgktj7xgktj'), d: { node: '117:6228', w: 286, h: 180, crop: [500, 151, 2200, 1385] }, m: { node: '117:6229', w: 260, h: 150, crop: [350, 151, 2400, 1385] } },
  // Grant, 2026-11-05 (later): 4.5 is the regenerated single-novel photo (yqdz, prompt P7-4b); card 3 recropped higher so it ends at the
  // table edge (no under-table view) and starts below the chins.
  { key: 'p45', src: G('yqdz2yyqdz2yyqdz'), d: { node: '117:6226', w: 360, h: 320, crop: [280, 420, 1768, 1572] }, m: { node: '117:6227', w: 335, h: 210, crop: [0, 520, 2048, 1284] } },
  { key: 'p410c', src: G('fzdo2nfzdo2nfzdo'), d: { node: '117:6232', w: 286, h: 180, crop: [820, 690, 874, 550] }, m: { node: '117:6233', w: 260, h: 150, crop: [780, 690, 953, 550] } }];
// Batch 4 (2026-11-06): v2.4 frame 135:412. The photos were cloned in from v2.3.3 inside Figma (hero tag now "Family · This year /
// Plan our family trip, two hours a month."). This places the 4.6 product UI (specs pillar-types-of-goals-shapes-v2.4*.json: faith daily
// marks, a run tally with no target, family trip tracked at the cycle report). 2026-11-07: desktop crop now takes the whole panel (1960x1018, rendered with --today 2026-11-06); the old 1790 crop cut off Friday, the Mark button and the right arrow. 2026-11-12 (Brandon, 2026-11-09): the run tally with no target is gone (the app has no target-free count mode); two rows, so the crops are 1960x840 and 1170x1030. The open goal is an editorial tally in the page instead. Usage: node place-p7-photos.js 4 → place-p7-batch4.js.
const B4 = { d: { node: '135:837', file: '../product-views/out/pillar-types-of-goals-shapes-v2.4-2000x1200-bare.png', w: 900, crop: [0, 0, 1960, 840] },
  m: { node: '135:1321', file: '../product-views/out/pillar-types-of-goals-shapes-v2.4-mobile-mobile-bare.png', w: 335, crop: [0, 30, 1170, 1030] } };
if (process.argv[2] === '4') (async () => {
  let js = header;
  for (const k of ['d', 'm']) { const s = B4[k]; const h = Math.round(s.w * s.crop[3] / s.crop[2]);
    const b = await cropFile(s.file, s.crop, s.w, h, path.join(dir, 'out', `p7-p46-ui-${k === 'd' ? 'desktop' : 'mobile'}.png`), true);
    js += `out.ui_${k} = await place('${s.node}', '${b}', ${s.w}, ${h}, 'Product UI · week-board v2.4 · ${k === 'd' ? 'desktop' : 'mobile'}', null, '', 1);\n`; }
  js += `figma.notify('P7 v2.4 product UI placed'); window.__place4 = out; return out;\n})()`;
  fs.writeFileSync(path.join(os.tmpdir(), 'place-p7-batch4.js'), js);
  console.log('batch4', Math.round(js.length / 1024), 'KB');
})();
else if (process.argv[2] === '3') (async () => {
  let js = header;
  for (const s of SWAP.filter(x => !process.argv[3] || process.argv[3].split(',').includes(x.key))) for (const k of ['d', 'm']) {
    const b = await cropFile('source/' + s.src, s[k].crop, s[k].w, s[k].h, path.join(dir, 'out', `p7-${s.key}-${k === 'd' ? 'desktop' : 'mobile'}.jpg`));
    js += `{ const n = await figma.getNodeByIdAsync('${s[k].node}'); n.fills = [{ type: 'IMAGE', imageHash: figma.createImage(figma.base64Decode('${b}')).hash, scaleMode: 'FILL' }]; out.${s.key}_${k} = n.id; }\n`;
  }
  js += `figma.notify('P7 swap placed'); return out;\n})()`;
  fs.writeFileSync(path.join(os.tmpdir(), 'place-p7-batch3.js'), js);
  console.log('batch3', Math.round(js.length / 1024), 'KB');
})();
else if (process.argv[2] === '2') (async () => {
  const o = n => path.join(dir, 'out', n);
  const p45d = await cropFile('source/' + B2.p45.src, B2.p45.d.crop, B2.p45.d.w, B2.p45.d.h, o('p7-p45-desktop.jpg'));
  const p45m = await cropFile('source/' + B2.p45.src, B2.p45.m.crop, B2.p45.m.w, B2.p45.m.h, o('p7-p45-mobile.jpg'));
  const ui = {};
  for (const k of ['d', 'm']) { const s = B2.ui[k]; const h = Math.round(s.w * s.crop[3] / s.crop[2]); ui[k] = { ...s, h, b64: await cropFile(s.file, s.crop, s.w, h, o(`p7-p47-ui-${k === 'd' ? 'desktop' : 'mobile'}.png`), true) }; }
  let js = header;
  js += `for (const [id, b] of [['${B2.p45.d.node}', '${p45d}'], ['${B2.p45.m.node}', '${p45m}']]) { const n = await figma.getNodeByIdAsync(id); n.fills = [{ type: 'IMAGE', imageHash: figma.createImage(figma.base64Decode(b)).hash, scaleMode: 'FILL' }]; }\n`;
  for (const k of ['d', 'm']) js += `out.ui_${k} = await place('${ui[k].node}', '${ui[k].b64}', ${ui[k].w}, ${ui[k].h}, 'Product UI · week-board · ${k === 'd' ? 'desktop' : 'mobile'}', null, '', 1);\n`;
  js += `figma.notify('P7 batch 2 placed'); return out;\n})()`;
  fs.writeFileSync(path.join(os.tmpdir(), 'place-p7-batch2.js'), js);
  console.log('batch2', Math.round(js.length / 1024), 'KB', JSON.stringify({ d: [ui.d.w, ui.d.h], m: [ui.m.w, ui.m.h] }));
})();
else (async () => {
  fs.mkdirSync(path.join(dir, 'out'), { recursive: true });
  let js = header;
  const sheet = createCanvas(1500, 300 * SLOTS.length); const g = sheet.getContext('2d'); g.fillStyle = '#fff'; g.fillRect(0, 0, 1500, 300 * SLOTS.length);
  for (const [i, s] of SLOTS.entries()) {
    const dOut = path.join(dir, 'out', `p7-${s.key}-desktop.jpg`), mOut = path.join(dir, 'out', `p7-${s.key}-mobile.jpg`);
    const d64 = await crop(s.src, s.d.crop, s.d.w, s.d.h, dOut);
    const m64 = await crop(s.src, s.m.crop, s.m.w, s.m.h, mOut);
    js += `out.${s.key}_d = await place('${s.d.node}', '${d64}', ${s.d.w}, ${s.d.h}, 'Photo · ${s.key} · desktop', ${JSON.stringify(s.tag || null)}, '${s.corner || ''}', 1);\n`;
    js += `out.${s.key}_m = await place('${s.m.node}', '${m64}', ${s.m.w}, ${s.m.h}, 'Photo · ${s.key} · mobile', ${JSON.stringify(s.tag || null)}, '${s.corner || ''}', 0.85);\n`;
    const a = await loadImage(dOut), b = await loadImage(mOut); const k = 280 / Math.max(a.height, b.height);
    g.drawImage(a, 10, i * 300 + 10, a.width * k, a.height * k); g.drawImage(b, 30 + a.width * k, i * 300 + 10, b.width * k, b.height * k);
    g.fillStyle = '#000'; g.font = '20px sans-serif'; g.fillText(s.key, 1380, i * 300 + 40);
  }
  js += `figma.notify('P7 photos placed'); return out;\n})()`;
  new Function('figma', 'return ' + js.replace(/^\(async \(\) => \{/, '(async () => {'));
  fs.writeFileSync(path.join(os.tmpdir(), 'place-p7.js'), js);
  fs.writeFileSync(path.join(dir, 'out', 'p7-crops-sheet.jpg'), sheet.toBuffer('image/jpeg', 75));
  console.log('script', Math.round(js.length / 1024), 'KB →', path.join(os.tmpdir(), 'place-p7.js'));
})();
